CREATE OR REPLACE FUNCTION public.add_consignment_item_v2(p_consignment_id uuid, p_sku text, p_batch_code text, p_box_code text, p_best_before_date date, p_expected_qty integer)
 RETURNS consignment_items
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_manifest public.consignments; v_item public.consignment_items;
begin
  if not public.is_staff() then raise exception 'Staff access required'; end if;
  if coalesce(p_expected_qty, 0) < 1 then raise exception 'Expected quantity must be positive'; end if;
  if nullif(trim(coalesce(p_batch_code, '')), '') is null then raise exception 'Batch code is required'; end if;
  if nullif(trim(coalesce(p_box_code, '')), '') is null then raise exception 'Box code is required'; end if;
  if p_best_before_date is null then raise exception 'Best-before date is required'; end if;
  select * into v_manifest from public.consignments where id = p_consignment_id for update;
  if not found then raise exception 'Consignment not found'; end if;
  if v_manifest.status <> 'Packing_Italy' then raise exception 'Manifest packing is closed'; end if;
  insert into public.consignment_items (
    consignment_id, sku, batch_code, box_code, best_before_date,
    expected_qty, italy_packed_qty, manila_scanned_qty
  ) values (
    p_consignment_id, p_sku, trim(p_batch_code), trim(p_box_code), p_best_before_date,
    p_expected_qty, 0, 0
  ) returning * into v_item;
  return v_item;
end;
$function$

CREATE OR REPLACE FUNCTION public.advance_consignment(p_consignment_id uuid, p_to_status text)
 RETURNS consignments
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_manifest public.consignments;
begin
  if not public.is_staff() then raise exception 'Staff access required'; end if;
  select * into v_manifest from public.consignments where id = p_consignment_id for update;
  if not found then raise exception 'Consignment not found'; end if;
  if not (
    (v_manifest.status = 'Packing_Italy' and p_to_status = 'In_Transit') or
    (v_manifest.status = 'In_Transit' and p_to_status = 'Arrived_Manila')
  ) then raise exception 'Invalid consignment transition'; end if;
  if p_to_status = 'In_Transit' and exists (
    select 1 from public.consignment_items
    where consignment_id = p_consignment_id
      and italy_packed_qty <> expected_qty
  ) then raise exception 'Every expected unit must be scan-packed before transit'; end if;
  update public.consignments
  set status = p_to_status,
      arrived_at = case when p_to_status = 'Arrived_Manila' then now() else arrived_at end
  where id = p_consignment_id returning * into v_manifest;
  return v_manifest;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_consignment_manifest(p_manifest_code text, p_shipment_reference text)
 RETURNS consignments
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_manifest public.consignments;
begin
  if not public.is_staff() then raise exception 'Staff access required'; end if;
  if nullif(trim(coalesce(p_manifest_code, '')), '') is null then
    raise exception 'Manifest code is required';
  end if;
  insert into public.consignments (
    manifest_code, flight_number, departure_city, destination_city, status
  ) values (
    trim(p_manifest_code),
    coalesce(nullif(trim(p_shipment_reference), ''), 'Schedule not recorded'),
    'Milan, Italy', 'Manila, Philippines', 'Packing_Italy'
  ) returning * into v_manifest;
  return v_manifest;
end;
$function$

CREATE OR REPLACE FUNCTION public.execute_admin_consignment_command_v1(p_action text, p_timestamp bigint, p_nonce uuid, p_idempotency_key uuid, p_payload_text text, p_signature text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := auth.uid();
  v_payload jsonb;
  v_payload_hash text;
  v_existing k2_private.admin_command_receipts;
  v_manifest public.consignments;
  v_item public.consignment_items;
  v_result jsonb;
  v_count integer;
  v_inserted integer;
  v_limit integer;
  v_before jsonb;
  v_today date := (transaction_timestamp() at time zone 'Asia/Manila')::date;
  v_latest date := make_date(extract(year from v_today)::integer+10,
    extract(month from v_today)::integer,1)+extract(day from v_today)::integer-1;
begin
  if not k2_private.verify_admin_bff_request(
    p_action,p_timestamp,p_nonce,p_idempotency_key,p_payload_text,p_signature
  ) then
    raise exception using errcode='28000',message='K2_ADMIN_REQUEST_REPLAYED';
  end if;
  if p_action not in (
    'consignment_create','consignment_add_line','consignment_scan',
    'consignment_advance','consignment_finalize'
  ) then
    raise exception using errcode='22023',message='K2_ADMIN_ACTION_INVALID';
  end if;

  v_payload := p_payload_text::jsonb;
  if jsonb_typeof(v_payload)<>'object' then
    raise exception using errcode='22023',message='K2_ADMIN_PAYLOAD_INVALID';
  end if;
  v_payload_hash := encode(extensions.digest(convert_to(p_payload_text,'UTF8'),'sha256'),'hex');

  select * into v_existing from k2_private.admin_command_receipts
  where actor_id=v_actor and action=p_action and idempotency_key=p_idempotency_key;
  if found then
    if v_existing.payload_hash<>v_payload_hash then
      raise exception using errcode='22023',message='K2_ADMIN_IDEMPOTENCY_CONFLICT';
    end if;
    if v_existing.result is null then
      raise exception using errcode='55000',message='K2_ADMIN_COMMAND_IN_PROGRESS';
    end if;
    return v_existing.result;
  end if;

  v_limit := case when p_action='consignment_scan' then 300 else 30 end;
  select count(*)::integer into v_count from k2_private.admin_command_receipts
  where actor_id=v_actor and action=p_action and created_at>now()-interval '1 minute';
  if v_count>=v_limit then
    raise exception using errcode='54000',message='K2_ADMIN_RATE_LIMITED';
  end if;

  insert into k2_private.admin_command_receipts(actor_id,action,idempotency_key,payload_hash)
  values(v_actor,p_action,p_idempotency_key,v_payload_hash) on conflict do nothing;
  get diagnostics v_inserted=row_count;
  if v_inserted=0 then
    select * into v_existing from k2_private.admin_command_receipts
    where actor_id=v_actor and action=p_action and idempotency_key=p_idempotency_key;
    if v_existing.payload_hash<>v_payload_hash then
      raise exception using errcode='22023',message='K2_ADMIN_IDEMPOTENCY_CONFLICT';
    end if;
    if v_existing.result is null then
      raise exception using errcode='55000',message='K2_ADMIN_COMMAND_IN_PROGRESS';
    end if;
    return v_existing.result;
  end if;

  if p_action='consignment_create' then
    if (v_payload-array['manifestCode','shipmentReference'])<>'{}'::jsonb
       or length(trim(coalesce(v_payload->>'manifestCode',''))) not between 3 and 80
       or length(trim(coalesce(v_payload->>'shipmentReference',''))) > 120 then
      raise exception using errcode='22023',message='K2_ADMIN_PAYLOAD_INVALID';
    end if;
    select * into v_manifest from public.create_consignment_manifest(
      trim(v_payload->>'manifestCode'),nullif(trim(v_payload->>'shipmentReference'),'')
    );
    insert into public.audit_logs(table_name,record_id,action,new_data,user_id)
    values('consignments',v_manifest.id::text,'INSERT',jsonb_build_object(
      'manifest_code',v_manifest.manifest_code,'shipment_reference',v_manifest.flight_number,
      'status',v_manifest.status,'source','admin_bff'
    ),v_actor);
    v_result:=jsonb_build_object(
      'consignmentId',v_manifest.id,'manifestCode',v_manifest.manifest_code,'status',v_manifest.status
    );

  elsif p_action='consignment_add_line' then
    if (v_payload-array['consignmentId','sku','batchCode','boxCode','bestBeforeDate','expectedQty'])<>'{}'::jsonb
       or coalesce(v_payload->>'consignmentId','') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
       or length(trim(coalesce(v_payload->>'sku',''))) not between 1 and 120
       or length(trim(coalesce(v_payload->>'batchCode',''))) not between 1 and 120
       or length(trim(coalesce(v_payload->>'boxCode',''))) not between 1 and 120
       or coalesce(v_payload->>'bestBeforeDate','') !~ '^\d{4}-\d{2}-\d{2}$'
       or (v_payload->>'bestBeforeDate')::date < v_today
       or (v_payload->>'bestBeforeDate')::date > v_latest
       or jsonb_typeof(v_payload->'expectedQty')<>'number'
       or (v_payload->>'expectedQty')::numeric<>trunc((v_payload->>'expectedQty')::numeric)
       or (v_payload->>'expectedQty')::integer not between 1 and 100000
       or not exists(select 1 from public.products p where p.sku=trim(v_payload->>'sku')) then
      raise exception using errcode='22023',message='K2_ADMIN_PAYLOAD_INVALID';
    end if;
    select * into v_item from public.add_consignment_item_v2(
      (v_payload->>'consignmentId')::uuid,trim(v_payload->>'sku'),
      trim(v_payload->>'batchCode'),trim(v_payload->>'boxCode'),
      (v_payload->>'bestBeforeDate')::date,(v_payload->>'expectedQty')::integer
    );
    insert into public.audit_logs(table_name,record_id,action,new_data,user_id)
    values('consignment_items',v_item.id::text,'INSERT',jsonb_build_object(
      'consignment_id',v_item.consignment_id,'sku',v_item.sku,'batch_code',v_item.batch_code,
      'box_code',v_item.box_code,'best_before_date',v_item.best_before_date,
      'expected_qty',v_item.expected_qty,'source','admin_bff'
    ),v_actor);
    v_result:=jsonb_build_object(
      'itemId',v_item.id,'consignmentId',v_item.consignment_id,'sku',v_item.sku,
      'expectedQty',v_item.expected_qty
    );

  elsif p_action='consignment_scan' then
    if (v_payload-array['consignmentId','itemId','stage','scannedCode'])<>'{}'::jsonb
       or coalesce(v_payload->>'consignmentId','') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
       or coalesce(v_payload->>'itemId','') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
       or coalesce(v_payload->>'stage','') not in ('milan','manila')
       or length(trim(coalesce(v_payload->>'scannedCode',''))) not between 1 and 120 then
      raise exception using errcode='22023',message='K2_ADMIN_PAYLOAD_INVALID';
    end if;
    select * into v_item from public.consignment_items
    where id=(v_payload->>'itemId')::uuid and consignment_id=(v_payload->>'consignmentId')::uuid;
    if not found then
      raise exception using errcode='22023',message='K2_ADMIN_PAYLOAD_INVALID';
    end if;
    if lower(trim(v_payload->>'scannedCode'))<>lower(v_item.sku)
       and not exists(
         select 1 from public.products p where p.sku=v_item.sku
         and nullif(trim(p.barcode),'') is not null
         and lower(trim(p.barcode))=lower(trim(v_payload->>'scannedCode'))
       ) then
      raise exception using errcode='22023',message='K2_SCAN_CODE_MISMATCH';
    end if;
    select * into v_item from public.record_consignment_item_scan(
      v_item.consignment_id,v_item.id,v_payload->>'stage'
    );
    v_result:=jsonb_build_object(
      'itemId',v_item.id,'consignmentId',v_item.consignment_id,'sku',v_item.sku,
      'stage',v_payload->>'stage','expectedQty',v_item.expected_qty,
      'italyPackedQty',v_item.italy_packed_qty,'manilaScannedQty',v_item.manila_scanned_qty,
      'status',v_item.status
    );

  elsif p_action='consignment_advance' then
    if (v_payload-array['consignmentId','toStatus','reason'])<>'{}'::jsonb
       or coalesce(v_payload->>'consignmentId','') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
       or coalesce(v_payload->>'toStatus','') not in ('In_Transit','Arrived_Manila')
       or length(trim(coalesce(v_payload->>'reason',''))) not between 10 and 500 then
      raise exception using errcode='22023',message='K2_ADMIN_PAYLOAD_INVALID';
    end if;
    select to_jsonb(c) into v_before from public.consignments c
    where c.id=(v_payload->>'consignmentId')::uuid;
    select * into v_manifest from public.advance_consignment(
      (v_payload->>'consignmentId')::uuid,v_payload->>'toStatus'
    );
    insert into public.audit_logs(table_name,record_id,action,old_data,new_data,user_id)
    values('consignments',v_manifest.id::text,'UPDATE',v_before,jsonb_build_object(
      'status',v_manifest.status,'reason',trim(v_payload->>'reason'),'source','admin_bff'
    ),v_actor);
    v_result:=jsonb_build_object(
      'consignmentId',v_manifest.id,'status',v_manifest.status,'reasonRecorded',true
    );

  else
    if (v_payload-array['consignmentId','notes','hub','custodian'])<>'{}'::jsonb
       or jsonb_typeof(v_payload->'notes') is distinct from 'string'
       or jsonb_typeof(v_payload->'hub') is distinct from 'string'
       or jsonb_typeof(v_payload->'custodian') is distinct from 'string'
       or length(trim(coalesce(v_payload->>'hub',''))) not between 1 and 120
       or length(trim(coalesce(v_payload->>'custodian',''))) not between 1 and 120
       or coalesce(v_payload->>'consignmentId','') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
       or length(trim(coalesce(v_payload->>'notes',''))) not between 10 and 1000 then
      raise exception using errcode='22023',message='K2_ADMIN_PAYLOAD_INVALID';
    end if;
    select to_jsonb(c) into v_before from public.consignments c
    where c.id=(v_payload->>'consignmentId')::uuid;
    select * into v_manifest from k2_private.finalize_consignment_receipt_v1(
      (v_payload->>'consignmentId')::uuid,trim(v_payload->>'notes'),trim(v_payload->>'hub'),trim(v_payload->>'custodian')
    );
    insert into public.audit_logs(table_name,record_id,action,old_data,new_data,user_id)
    values('consignments',v_manifest.id::text,'UPDATE',v_before,jsonb_build_object(
      'status',v_manifest.status,'receipt_notes',trim(v_payload->>'notes'),'hub',trim(v_payload->>'hub'),'custodian',trim(v_payload->>'custodian'),'source','admin_bff'
    ),v_actor);
    v_result:=jsonb_build_object(
      'consignmentId',v_manifest.id,'status',v_manifest.status,'inventoryFinalized',true
    );
  end if;

  update k2_private.admin_command_receipts set result=v_result,completed_at=now()
  where actor_id=v_actor and action=p_action and idempotency_key=p_idempotency_key;
  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION public.generate_k2_sku_internal()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_sku text;
begin
  loop
    v_sku := 'K2-SKU-' || lpad(nextval('public.k2_sku_seq'::regclass)::text, 6, '0');
    exit when not exists (
      select 1 from public.products where upper(sku) = upper(v_sku)
    );
  end loop;
  return v_sku;
end;
$function$

CREATE OR REPLACE FUNCTION k2_private.finalize_consignment_receipt_v1(p_consignment_id uuid, p_notes text, p_hub text, p_custodian text)
 RETURNS consignments
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_manifest public.consignments; v_item public.consignment_items; v_balance public.inventory_balances; v_missing integer; v_status text;
  v_saved public.product_batches; v_before_balance public.inventory_balances;
  v_sku text; v_sellable integer;
  v_today date; v_instant timestamptz; v_depth integer; v_minimum integer; v_days numeric;
begin
  if not public.is_staff() then raise exception 'Staff access required'; end if;
  perform k2_private.lock_category_policy_v1(false);
  select maximum_depth into v_depth from k2_private.category_policy_command_config where singleton;
  if v_depth is null or v_depth<1 then
    raise exception using errcode='55000',message='K2_CATEGORY_POLICY_NOT_CONFIGURED';
  end if;
  if not exists(select 1 from public.hubs h join public.custodians c on c.hub_id=h.id
    where h.id=p_hub and h.id='HUB-MNL-CENTRAL' and h.country='PH' and c.id=p_custodian) then
    raise exception 'K2_RECEIVING_CUSTODY_INVALID'; end if;
  select * into v_manifest from public.consignments where id = p_consignment_id for update;
  if not found then raise exception 'Consignment not found'; end if;
  if v_manifest.status = 'Completed' then raise exception 'K2_RECEIVING_ALREADY_COMPLETED'; end if;
  if v_manifest.status <> 'Arrived_Manila' then raise exception 'Consignment must be in Arrived Manila state'; end if;
  if not exists (select 1 from public.consignment_items where consignment_id = p_consignment_id) then raise exception 'Cannot finalize an empty manifest'; end if;

  -- Acquire every common SKU balance before product/lot work, in SKU order.
  for v_sku in select distinct sku from public.consignment_items where consignment_id=p_consignment_id order by sku
  loop
    insert into public.inventory_balances(sku,location_code,on_hand,reserved)
    select v_sku,'MANILA_MAIN',coalesce(sum(b.quantity),0)::integer,coalesce(sum(b.reserved_quantity),0)::integer
    from public.product_batches b where b.sku=v_sku
    on conflict(sku,location_code) do nothing;
    perform 1 from public.inventory_balances where sku=v_sku and location_code='MANILA_MAIN' for update;
  end loop;
  perform 1 from public.products where sku in (select sku from public.consignment_items where consignment_id=p_consignment_id)
    order by sku for update;
  perform 1 from public.consignment_items where consignment_id=p_consignment_id order by sku,id for update;
  perform 1 from public.product_batches where sku in (
    select sku from public.consignment_items where consignment_id=p_consignment_id
  ) order by sku,id for update;
  -- One internal server instant after every existing affected resource lock.
  v_instant:=k2_private.start_category_lot_context_v1(v_depth);
  v_today:=(v_instant at time zone 'Asia/Manila')::date;
  for v_item in select * from public.consignment_items where consignment_id = p_consignment_id order by sku,id for update
  loop
    select * into v_before_balance from public.inventory_balances where sku=v_item.sku and location_code='MANILA_MAIN';
    if v_item.manila_scanned_qty > 0 then
      select k2_private.effective_category_minimum_v1(p.category_id,v_depth) into v_minimum
      from public.products p where p.sku=v_item.sku;
      if v_minimum is null then
        raise exception using errcode='23514',message='K2_CATEGORY_POLICY_TAXONOMY_INVALID';
      end if;
      v_days:=null;
      if v_item.best_before_date is not null and pg_catalog.isfinite(v_item.best_before_date) then
        v_days:=(v_item.best_before_date-date '2000-01-01')::numeric-(v_today-date '2000-01-01')::numeric;
      end if;
      v_status := case when v_days>=v_minimum then 'available' else 'quarantine' end;
      insert into public.product_batches (
        sku, box_code, batch_code, quantity, quantity_available, reserved_quantity,
        expiry_date, best_before_date, landed_date, hub, custodian, arrival_flight,
        inventory_status, source_consignment_item_id, unit_cost, updated_at
      ) values (
        v_item.sku, v_item.box_code, v_item.batch_code,
        v_item.manila_scanned_qty, v_item.manila_scanned_qty, 0,
        v_item.best_before_date, v_item.best_before_date, v_today,
        p_hub, p_custodian, v_manifest.manifest_code, v_status, v_item.id, v_item.unit_cost, now()
      ) returning * into v_saved;
      insert into public.inventory_balances (sku, location_code, on_hand)
      values (v_item.sku, 'MANILA_MAIN', v_item.manila_scanned_qty)
      on conflict (sku, location_code) do update set on_hand = inventory_balances.on_hand + excluded.on_hand, updated_at = now();
      select * into v_balance from public.inventory_balances where sku = v_item.sku and location_code = 'MANILA_MAIN';
      perform set_config('k2.allow_stock_write', 'on', true);
      select coalesce(sum(greatest(b.quantity-b.reserved_quantity,0)),0)::integer into v_sellable
      from public.product_batches b where b.sku=v_item.sku and k2_private.lot_is_eligible_for_category_v1(b,v_depth,v_instant);
      update public.products set stock_available=v_sellable,total_stock=v_sellable where sku=v_item.sku;
      insert into public.inventory_events (sku, location_code, event_type, quantity, reference_type, reference_id, reason, actor_id, metadata)
      values (v_item.sku, 'MANILA_MAIN', 'received', v_item.manila_scanned_qty, 'consignment', v_manifest.id,
        p_notes, auth.uid(), jsonb_build_object('manifest', v_manifest.manifest_code, 'batch_code', v_item.batch_code,
        'box_code', v_item.box_code, 'inventory_status', v_saved.inventory_status,
        'batch_id',v_saved.id,'source_consignment_item_id',v_item.id,'hub',v_saved.hub,'custodian',v_saved.custodian,
        'quantity_available',v_saved.quantity_available,'batch_after',to_jsonb(v_saved),
        'balance_before',to_jsonb(v_before_balance),'balance_after',to_jsonb(v_balance)));
    end if;
    v_missing := v_item.italy_packed_qty - v_item.manila_scanned_qty;
    if v_missing > 0 then
      insert into public.inventory_events (sku, location_code, event_type, quantity, reference_type, reference_id, reason, actor_id, metadata)
      values (v_item.sku, 'MANILA_MAIN', 'reconciled', v_missing, 'consignment', v_manifest.id,
        p_notes, auth.uid(), jsonb_build_object('result', 'missing_on_arrival', 'manifest', v_manifest.manifest_code,
        'batch_code', v_item.batch_code, 'box_code', v_item.box_code,
        'source_consignment_item_id',v_item.id,'hub',p_hub,'custodian',p_custodian,
        'expected_qty',v_item.expected_qty,'italy_packed_qty',v_item.italy_packed_qty,'manila_scanned_qty',v_item.manila_scanned_qty));
    end if;
  end loop;
  update public.consignments set status = 'Completed', arrived_at = coalesce(arrived_at, now())
  where id = p_consignment_id returning * into v_manifest;
  perform k2_private.clear_category_lot_context_v1();
  return v_manifest;
end;
$function$

CREATE OR REPLACE FUNCTION k2_private.verify_admin_bff_request(p_action text, p_timestamp bigint, p_nonce uuid, p_idempotency_key uuid, p_payload_text text, p_signature text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := auth.uid();
  v_secret bytea;
  v_payload_hash text;
  v_expected text;
  v_message text;
  v_bucket_start timestamptz;
  v_actor_hits integer;
  v_global_hits integer;
begin
  if v_actor is null or not public.is_staff() then
    raise exception using errcode='42501',message='K2_ADMIN_ACCESS_REQUIRED';
  end if;
  if coalesce(auth.jwt()->>'aal','')<>'aal2' then
    raise exception using errcode='42501',message='K2_ADMIN_AAL2_REQUIRED';
  end if;
  if p_action is null or p_timestamp is null or p_nonce is null
     or p_idempotency_key is null or p_payload_text is null or p_signature is null then
    raise exception using errcode='22023',message='K2_ADMIN_REQUEST_INVALID';
  end if;
  if p_action not in ('reference_create','cancel_order','delivery_express_quote','delivery_customer_rates_publish',
    'confirm_order', 'packing_scan', 'payment_status', 'delivery_details',
    'fulfill_order', 'transfer_lot', 'assign_box',
    'inbox_internal_note', 'inbox_mark_read', 'inbox_workflow',
    'pasabuy_transition', 'pasabuy_quote',
    'intake_session_create', 'intake_session_step', 'intake_draft',
    'intake_inventory', 'intake_publication', 'intake_evidence_register',
    'consignment_create', 'consignment_add_line', 'consignment_scan',
    'consignment_advance', 'consignment_finalize',
    'lots_reconcile', 'lot_clearance',
    'coupon_create', 'coupon_state', 'coupon_archive',
    'admin_session_register', 'admin_session_validate',
    'admin_session_revoke_current', 'admin_session_revoke_one', 'admin_session_revoke_all',
    'admin_session_list',
    'catalog_import_chunk',
    'wholesale_inquiry_review',
    'admin_mfa_replacement_requested', 'admin_mfa_replacement_completed',
    'product_media_upload', 'product_media_assign', 'product_media_cleanup_complete',
    'product_media_orphan_cleanup', 'product_media_orphan_cleanup_complete',
    'globe_config_update', 'review_create', 'review_update', 'review_publish', 'review_withdraw',
    'supplier_create',
    'channel_internal_event_verify', 'website_listing_set',
    'staff_role_change', 'admin_delete_pin_set',
    'product_sku_merge', 'product_master_update', 'product_master_status', 'product_master_delete',
    'category_policy_set', 'category_policy_clear',
    'inbox_send_reply', 'product_knowledge_save', 'product_family_save',
    'ai_spend_controls_update'
  ) then
    raise exception using errcode='22023',message='K2_ADMIN_ACTION_INVALID';
  end if;
  if p_payload_text is null or octet_length(convert_to(p_payload_text, 'UTF8')) >
       (case when p_action='catalog_import_chunk' then 1048576 else 16384 end)
     or p_signature !~ '^[0-9a-f]{64}$' then
    raise exception using errcode='22023',message='K2_ADMIN_REQUEST_INVALID';
  end if;
  if abs(extract(epoch from clock_timestamp())::bigint - p_timestamp)>300 then
    raise exception using errcode='28000',message='K2_ADMIN_SIGNATURE_EXPIRED';
  end if;
  select request_secret into v_secret
  from k2_private.admin_bff_secrets where singleton = true;
  if v_secret is null then
    raise exception using errcode='55000', message='K2_ADMIN_BOUNDARY_NOT_CONFIGURED';
  end if;

  v_payload_hash := encode(extensions.digest(convert_to(p_payload_text, 'UTF8'), 'sha256'), 'hex');
  v_message := p_action || E'\n' || p_timestamp::text || E'\n' || p_nonce::text
    || E'\n' || v_actor::text || E'\n' || p_idempotency_key::text || E'\n' || v_payload_hash;
  v_expected := encode(extensions.hmac(convert_to(v_message, 'UTF8'), v_secret, 'sha256'), 'hex');
  if extensions.digest(convert_to(v_expected, 'UTF8'), 'sha256')
     <> extensions.digest(convert_to(p_signature, 'UTF8'), 'sha256') then
    raise exception using errcode='28000', message='K2_ADMIN_SIGNATURE_INVALID';
  end if;

  v_bucket_start := date_trunc('minute', clock_timestamp());
  delete from k2_private.admin_request_rate_buckets
  where bucket_start < v_bucket_start - interval '1 day';
  insert into k2_private.admin_request_rate_buckets(scope, subject, bucket_start, hit_count)
  values ('actor', v_actor::text, v_bucket_start, 1)
  on conflict (scope, subject, bucket_start) do update
    set hit_count = k2_private.admin_request_rate_buckets.hit_count + 1
  returning hit_count into v_actor_hits;
  if v_actor_hits > 360 then
    raise exception using errcode='54000', message='K2_ADMIN_RATE_LIMITED';
  end if;
  insert into k2_private.admin_request_rate_buckets(scope, subject, bucket_start, hit_count)
  values ('global', 'all_admin_requests', v_bucket_start, 1)
  on conflict (scope, subject, bucket_start) do update
    set hit_count = k2_private.admin_request_rate_buckets.hit_count + 1
  returning hit_count into v_global_hits;
  if v_global_hits > 6000 then
    raise exception using errcode='54000', message='K2_ADMIN_RATE_LIMITED';
  end if;

  delete from k2_private.admin_request_nonces where expires_at<=now();
  insert into k2_private.admin_request_nonces(actor_id,action,nonce,expires_at,verified_backend_pid,verified_transaction_id)
  values(v_actor,p_action,p_nonce,now()+interval '10 minutes',pg_backend_pid(),pg_current_xact_id()) on conflict do nothing;
  return found;
end;
$function$

CREATE OR REPLACE FUNCTION public.record_consignment_item_scan(p_consignment_id uuid, p_consignment_item_id uuid, p_stage text)
 RETURNS consignment_items
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_manifest public.consignments; v_item public.consignment_items; v_result integer;
begin
  if not public.is_staff() then raise exception 'Staff access required'; end if;
  select * into v_manifest from public.consignments where id = p_consignment_id for update;
  if not found then raise exception 'Consignment not found'; end if;
  select * into v_item from public.consignment_items
  where id = p_consignment_item_id and consignment_id = p_consignment_id for update;
  if not found then raise exception 'Manifest line not found'; end if;
  if p_stage = 'milan' then
    if v_manifest.status <> 'Packing_Italy' then raise exception 'Milan packing is closed'; end if;
    if v_item.italy_packed_qty >= v_item.expected_qty then raise exception 'Packed scans cannot exceed expected quantity'; end if;
    update public.consignment_items set italy_packed_qty = italy_packed_qty + 1
    where id = v_item.id returning * into v_item;
    v_result := v_item.italy_packed_qty;
  elsif p_stage = 'manila' then
    if v_manifest.status <> 'Arrived_Manila' then raise exception 'Consignment is not ready for Manila receiving'; end if;
    if v_item.manila_scanned_qty >= v_item.italy_packed_qty then raise exception 'Received scans cannot exceed Milan packed quantity'; end if;
    update public.consignment_items set manila_scanned_qty = manila_scanned_qty + 1,
      status = case when manila_scanned_qty + 1 = italy_packed_qty then 'Matched' else 'Discrepancy' end
    where id = v_item.id returning * into v_item;
    v_result := v_item.manila_scanned_qty;
  else raise exception 'Stage must be milan or manila';
  end if;
  insert into public.consignment_scan_events (
    consignment_id, consignment_item_id, sku, stage, resulting_qty, actor_id
  ) values (v_manifest.id, v_item.id, v_item.sku, p_stage, v_result, auth.uid());
  return v_item;
end;
$function$

CREATE OR REPLACE FUNCTION public.add_consignment_item_v2(p_consignment_id uuid, p_sku text, p_batch_code text, p_box_code text, p_best_before_date date, p_expected_qty integer)
 RETURNS consignment_items
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_manifest public.consignments; v_item public.consignment_items;
begin
  if not public.is_staff() then raise exception 'Staff access required'; end if;
  if coalesce(p_expected_qty, 0) < 1 then raise exception 'Expected quantity must be positive'; end if;
  if nullif(trim(coalesce(p_batch_code, '')), '') is null then raise exception 'Batch code is required'; end if;
  if nullif(trim(coalesce(p_box_code, '')), '') is null then raise exception 'Box code is required'; end if;
  if p_best_before_date is null then raise exception 'Best-before date is required'; end if;
  select * into v_manifest from public.consignments where id = p_consignment_id for update;
  if not found then raise exception 'Consignment not found'; end if;
  if v_manifest.status <> 'Packing_Italy' then raise exception 'Manifest packing is closed'; end if;
  insert into public.consignment_items (
    consignment_id, sku, batch_code, box_code, best_before_date,
    expected_qty, italy_packed_qty, manila_scanned_qty
  ) values (
    p_consignment_id, p_sku, trim(p_batch_code), trim(p_box_code), p_best_before_date,
    p_expected_qty, 0, 0
  ) returning * into v_item;
  return v_item;
end;
$function$

CREATE OR REPLACE FUNCTION public.advance_consignment(p_consignment_id uuid, p_to_status text)
 RETURNS consignments
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_manifest public.consignments;
begin
  if not public.is_staff() then raise exception 'Staff access required'; end if;
  select * into v_manifest from public.consignments where id = p_consignment_id for update;
  if not found then raise exception 'Consignment not found'; end if;
  if not (
    (v_manifest.status = 'Packing_Italy' and p_to_status = 'In_Transit') or
    (v_manifest.status = 'In_Transit' and p_to_status = 'Arrived_Manila')
  ) then raise exception 'Invalid consignment transition'; end if;
  if p_to_status = 'In_Transit' and exists (
    select 1 from public.consignment_items
    where consignment_id = p_consignment_id
      and italy_packed_qty <> expected_qty
  ) then raise exception 'Every expected unit must be scan-packed before transit'; end if;
  update public.consignments
  set status = p_to_status,
      arrived_at = case when p_to_status = 'Arrived_Manila' then now() else arrived_at end
  where id = p_consignment_id returning * into v_manifest;
  return v_manifest;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_consignment_manifest(p_manifest_code text, p_shipment_reference text)
 RETURNS consignments
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_manifest public.consignments;
begin
  if not public.is_staff() then raise exception 'Staff access required'; end if;
  if nullif(trim(coalesce(p_manifest_code, '')), '') is null then
    raise exception 'Manifest code is required';
  end if;
  insert into public.consignments (
    manifest_code, flight_number, departure_city, destination_city, status
  ) values (
    trim(p_manifest_code),
    coalesce(nullif(trim(p_shipment_reference), ''), 'Schedule not recorded'),
    'Milan, Italy', 'Manila, Philippines', 'Packing_Italy'
  ) returning * into v_manifest;
  return v_manifest;
end;
$function$

CREATE OR REPLACE FUNCTION public.execute_admin_consignment_command_v1(p_action text, p_timestamp bigint, p_nonce uuid, p_idempotency_key uuid, p_payload_text text, p_signature text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := auth.uid();
  v_payload jsonb;
  v_payload_hash text;
  v_existing k2_private.admin_command_receipts;
  v_manifest public.consignments;
  v_item public.consignment_items;
  v_result jsonb;
  v_count integer;
  v_inserted integer;
  v_limit integer;
  v_before jsonb;
  v_today date := (transaction_timestamp() at time zone 'Asia/Manila')::date;
  v_latest date := make_date(extract(year from v_today)::integer+10,
    extract(month from v_today)::integer,1)+extract(day from v_today)::integer-1;
begin
  if not k2_private.verify_admin_bff_request(
    p_action,p_timestamp,p_nonce,p_idempotency_key,p_payload_text,p_signature
  ) then
    raise exception using errcode='28000',message='K2_ADMIN_REQUEST_REPLAYED';
  end if;
  if p_action not in (
    'consignment_create','consignment_add_line','consignment_scan',
    'consignment_advance','consignment_finalize','consignment_packing'
  ) then
    raise exception using errcode='22023',message='K2_ADMIN_ACTION_INVALID';
  end if;

  v_payload := p_payload_text::jsonb;
  if jsonb_typeof(v_payload)<>'object' then
    raise exception using errcode='22023',message='K2_ADMIN_PAYLOAD_INVALID';
  end if;
  v_payload_hash := encode(extensions.digest(convert_to(p_payload_text,'UTF8'),'sha256'),'hex');

  select * into v_existing from k2_private.admin_command_receipts
  where actor_id=v_actor and action=p_action and idempotency_key=p_idempotency_key;
  if found then
    if v_existing.payload_hash<>v_payload_hash then
      raise exception using errcode='22023',message='K2_ADMIN_IDEMPOTENCY_CONFLICT';
    end if;
    if v_existing.result is null then
      raise exception using errcode='55000',message='K2_ADMIN_COMMAND_IN_PROGRESS';
    end if;
    return v_existing.result;
  end if;

  v_limit := case when p_action in ('consignment_scan','consignment_packing') then 300 else 30 end;
  select count(*)::integer into v_count from k2_private.admin_command_receipts
  where actor_id=v_actor and action=p_action and created_at>now()-interval '1 minute';
  if v_count>=v_limit then
    raise exception using errcode='54000',message='K2_ADMIN_RATE_LIMITED';
  end if;

  insert into k2_private.admin_command_receipts(actor_id,action,idempotency_key,payload_hash)
  values(v_actor,p_action,p_idempotency_key,v_payload_hash) on conflict do nothing;
  get diagnostics v_inserted=row_count;
  if v_inserted=0 then
    select * into v_existing from k2_private.admin_command_receipts
    where actor_id=v_actor and action=p_action and idempotency_key=p_idempotency_key;
    if v_existing.payload_hash<>v_payload_hash then
      raise exception using errcode='22023',message='K2_ADMIN_IDEMPOTENCY_CONFLICT';
    end if;
    if v_existing.result is null then
      raise exception using errcode='55000',message='K2_ADMIN_COMMAND_IN_PROGRESS';
    end if;
    return v_existing.result;
  end if;

  if p_action='consignment_packing' then
    v_result:=k2_private.apply_consignment_packing_v1(v_actor,v_payload);
    update k2_private.admin_command_receipts set result=v_result,completed_at=now()
      where actor_id=v_actor and action=p_action and idempotency_key=p_idempotency_key;
    return v_result;
  end if;
  -- Historical receipts above remain replayable. Fresh dispatch must bind review.
  if p_action='consignment_advance' and v_payload->>'toStatus'='In_Transit' then
    raise exception 'K2_PACKING_REVIEW_STALE';
  end if;
  if p_action='consignment_create' then
    if (v_payload-array['manifestCode','shipmentReference'])<>'{}'::jsonb
       or length(trim(coalesce(v_payload->>'manifestCode',''))) not between 3 and 80
       or length(trim(coalesce(v_payload->>'shipmentReference',''))) > 120 then
      raise exception using errcode='22023',message='K2_ADMIN_PAYLOAD_INVALID';
    end if;
    select * into v_manifest from public.create_consignment_manifest(
      trim(v_payload->>'manifestCode'),nullif(trim(v_payload->>'shipmentReference'),'')
    );
    insert into public.audit_logs(table_name,record_id,action,new_data,user_id)
    values('consignments',v_manifest.id::text,'INSERT',jsonb_build_object(
      'manifest_code',v_manifest.manifest_code,'shipment_reference',v_manifest.flight_number,
      'status',v_manifest.status,'source','admin_bff'
    ),v_actor);
    v_result:=jsonb_build_object(
      'consignmentId',v_manifest.id,'manifestCode',v_manifest.manifest_code,'status',v_manifest.status
    );

  elsif p_action='consignment_add_line' then
    if (v_payload-array['consignmentId','sku','batchCode','boxCode','bestBeforeDate','expectedQty'])<>'{}'::jsonb
       or coalesce(v_payload->>'consignmentId','') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
       or length(trim(coalesce(v_payload->>'sku',''))) not between 1 and 120
       or length(trim(coalesce(v_payload->>'batchCode',''))) not between 1 and 120
       or length(trim(coalesce(v_payload->>'boxCode',''))) not between 1 and 120
       or coalesce(v_payload->>'bestBeforeDate','') !~ '^\d{4}-\d{2}-\d{2}$'
       or (v_payload->>'bestBeforeDate')::date < v_today
       or (v_payload->>'bestBeforeDate')::date > v_latest
       or jsonb_typeof(v_payload->'expectedQty')<>'number'
       or (v_payload->>'expectedQty')::numeric<>trunc((v_payload->>'expectedQty')::numeric)
       or (v_payload->>'expectedQty')::integer not between 1 and 100000
       or not exists(select 1 from public.products p where p.sku=trim(v_payload->>'sku')) then
      raise exception using errcode='22023',message='K2_ADMIN_PAYLOAD_INVALID';
    end if;
    select * into v_item from public.add_consignment_item_v2(
      (v_payload->>'consignmentId')::uuid,trim(v_payload->>'sku'),
      trim(v_payload->>'batchCode'),trim(v_payload->>'boxCode'),
      (v_payload->>'bestBeforeDate')::date,(v_payload->>'expectedQty')::integer
    );
    insert into public.audit_logs(table_name,record_id,action,new_data,user_id)
    values('consignment_items',v_item.id::text,'INSERT',jsonb_build_object(
      'consignment_id',v_item.consignment_id,'sku',v_item.sku,'batch_code',v_item.batch_code,
      'box_code',v_item.box_code,'best_before_date',v_item.best_before_date,
      'expected_qty',v_item.expected_qty,'source','admin_bff'
    ),v_actor);
    v_result:=jsonb_build_object(
      'itemId',v_item.id,'consignmentId',v_item.consignment_id,'sku',v_item.sku,
      'expectedQty',v_item.expected_qty
    );

  elsif p_action='consignment_scan' then
    if (v_payload-array['consignmentId','itemId','stage','scannedCode'])<>'{}'::jsonb
       or coalesce(v_payload->>'consignmentId','') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
       or coalesce(v_payload->>'itemId','') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
       or coalesce(v_payload->>'stage','') not in ('milan','manila')
       or length(trim(coalesce(v_payload->>'scannedCode',''))) not between 1 and 120 then
      raise exception using errcode='22023',message='K2_ADMIN_PAYLOAD_INVALID';
    end if;
    select * into v_item from public.consignment_items
    where id=(v_payload->>'itemId')::uuid and consignment_id=(v_payload->>'consignmentId')::uuid;
    if not found then
      raise exception using errcode='22023',message='K2_ADMIN_PAYLOAD_INVALID';
    end if;
    if lower(trim(v_payload->>'scannedCode'))<>lower(v_item.sku)
       and not exists(
         select 1 from public.products p where p.sku=v_item.sku
         and nullif(trim(p.barcode),'') is not null
         and lower(trim(p.barcode))=lower(trim(v_payload->>'scannedCode'))
       ) then
      raise exception using errcode='22023',message='K2_SCAN_CODE_MISMATCH';
    end if;
    select * into v_item from public.record_consignment_item_scan(
      v_item.consignment_id,v_item.id,v_payload->>'stage'
    );
    v_result:=jsonb_build_object(
      'itemId',v_item.id,'consignmentId',v_item.consignment_id,'sku',v_item.sku,
      'stage',v_payload->>'stage','expectedQty',v_item.expected_qty,
      'italyPackedQty',v_item.italy_packed_qty,'manilaScannedQty',v_item.manila_scanned_qty,
      'status',v_item.status
    );

  elsif p_action='consignment_advance' then
    if (v_payload-array['consignmentId','toStatus','reason'])<>'{}'::jsonb
       or coalesce(v_payload->>'consignmentId','') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
       or coalesce(v_payload->>'toStatus','') not in ('In_Transit','Arrived_Manila')
       or length(trim(coalesce(v_payload->>'reason',''))) not between 10 and 500 then
      raise exception using errcode='22023',message='K2_ADMIN_PAYLOAD_INVALID';
    end if;
    select to_jsonb(c) into v_before from public.consignments c
    where c.id=(v_payload->>'consignmentId')::uuid;
    select * into v_manifest from public.advance_consignment(
      (v_payload->>'consignmentId')::uuid,v_payload->>'toStatus'
    );
    insert into public.audit_logs(table_name,record_id,action,old_data,new_data,user_id)
    values('consignments',v_manifest.id::text,'UPDATE',v_before,jsonb_build_object(
      'status',v_manifest.status,'reason',trim(v_payload->>'reason'),'source','admin_bff'
    ),v_actor);
    v_result:=jsonb_build_object(
      'consignmentId',v_manifest.id,'status',v_manifest.status,'reasonRecorded',true
    );

  else
    if (v_payload-array['consignmentId','notes','hub','custodian'])<>'{}'::jsonb
       or jsonb_typeof(v_payload->'notes') is distinct from 'string'
       or jsonb_typeof(v_payload->'hub') is distinct from 'string'
       or jsonb_typeof(v_payload->'custodian') is distinct from 'string'
       or length(trim(coalesce(v_payload->>'hub',''))) not between 1 and 120
       or length(trim(coalesce(v_payload->>'custodian',''))) not between 1 and 120
       or coalesce(v_payload->>'consignmentId','') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
       or length(trim(coalesce(v_payload->>'notes',''))) not between 10 and 1000 then
      raise exception using errcode='22023',message='K2_ADMIN_PAYLOAD_INVALID';
    end if;
    select to_jsonb(c) into v_before from public.consignments c
    where c.id=(v_payload->>'consignmentId')::uuid;
    select * into v_manifest from k2_private.finalize_consignment_receipt_v1(
      (v_payload->>'consignmentId')::uuid,trim(v_payload->>'notes'),trim(v_payload->>'hub'),trim(v_payload->>'custodian')
    );
    insert into public.audit_logs(table_name,record_id,action,old_data,new_data,user_id)
    values('consignments',v_manifest.id::text,'UPDATE',v_before,jsonb_build_object(
      'status',v_manifest.status,'receipt_notes',trim(v_payload->>'notes'),'hub',trim(v_payload->>'hub'),'custodian',trim(v_payload->>'custodian'),'source','admin_bff'
    ),v_actor);
    v_result:=jsonb_build_object(
      'consignmentId',v_manifest.id,'status',v_manifest.status,'inventoryFinalized',true
    );
  end if;

  update k2_private.admin_command_receipts set result=v_result,completed_at=now()
  where actor_id=v_actor and action=p_action and idempotency_key=p_idempotency_key;
  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION public.generate_k2_sku_internal()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_sku text;
begin
  loop
    v_sku := 'K2-SKU-' || lpad(nextval('public.k2_sku_seq'::regclass)::text, 6, '0');
    exit when not exists (
      select 1 from public.products where upper(sku) = upper(v_sku)
    );
  end loop;
  return v_sku;
end;
$function$

CREATE OR REPLACE FUNCTION k2_private.apply_consignment_packing_v1(p_actor uuid, p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c public.consignments; i public.consignment_items; product public.products;
 op text:=p->>'operation'; before_row jsonb; code text:=trim(p->>'code'); matches integer;
 delta integer; expiry date; sku text; removed jsonb; stamp date:=(clock_timestamp() at time zone 'Asia/Manila')::date;
begin
 if p_actor is distinct from auth.uid() or public.is_staff() is distinct from true
   or coalesce(auth.jwt()->>'aal','')<>'aal2' then raise exception using errcode='42501',message='K2_STAFF_REQUIRED'; end if;
 select * into c from public.consignments where id=(p->>'consignmentId')::uuid for update;
 if not found or c.status<>'Packing_Italy' then raise exception 'K2_PACKING_CLOSED'; end if;
 if op='reopen' then
  if c.packing_cancelled_at is null then raise exception 'K2_PACKING_CLOSED'; end if;
 elsif c.packing_cancelled_at is not null then raise exception 'K2_PACKING_CLOSED'; end if;
 if op<>'count' then
  if jsonb_typeof(p->'packingRevision') is distinct from 'number'
    or (p->>'packingRevision')::numeric<>c.packing_revision then raise exception 'K2_PACKING_REVIEW_STALE'; end if;
  if length(trim(coalesce(p->>'reason',''))) not between 1 and 500 then raise exception 'K2_ADMIN_PAYLOAD_INVALID'; end if;
 end if;
 if op='count' then
  if (p-array['operation','consignmentId','itemId','code','boxCode','batchCode','bestBeforeDate','delta','source'])<>'{}'
    or p->>'source' not in ('barcode','counter') or jsonb_typeof(p->'delta') is distinct from 'number'
    or (p->>'delta')::numeric not in (-1,1) or length(coalesce(code,'')) not between 1 and 120
    or length(trim(coalesce(p->>'boxCode',''))) not between 1 and 120
    or length(trim(coalesce(p->>'batchCode',''))) not between 1 and 120 then raise exception 'K2_ADMIN_PAYLOAD_INVALID'; end if;
  delta:=(p->>'delta')::integer;
  expiry:=(p->>'bestBeforeDate')::date;
  if expiry is null or expiry<stamp or expiry>(stamp+interval '10 years')::date then raise exception 'K2_PACKING_DATE_INVALID'; end if;
  if p->>'itemId' is not null then
   select * into i from public.consignment_items where id=(p->>'itemId')::uuid and consignment_id=c.id for update;
   if not found then raise exception 'K2_PACKING_LOT_MISMATCH'; end if;
   if i.packing_removed_at is not null then raise exception 'K2_PACKING_ITEM_REMOVED'; end if;
   if row(i.box_code,i.batch_code,i.best_before_date) is distinct from row(trim(p->>'boxCode'),trim(p->>'batchCode'),expiry)
     then raise exception 'K2_PACKING_LOT_MISMATCH'; end if;
   select * into product from public.products where products.sku=i.sku;
   if lower(code)<>lower(i.sku) and lower(code) is distinct from lower(trim(product.barcode)) then raise exception 'K2_SCAN_CODE_MISMATCH'; end if;
  else
   if delta<>1 or p->>'source'<>'barcode' then raise exception 'K2_ADMIN_PAYLOAD_INVALID'; end if;
   -- Cooperate with the canonical Draft and Product Master barcode admission lock.
   perform pg_advisory_xact_lock(hashtextextended('k2.draft.barcode:'||lower(code),0));
   select count(*) into matches from public.products where lower(trim(products.barcode))=lower(code) or lower(products.sku)=lower(code);
   if matches>1 then raise exception 'K2_PACKING_IDENTITY_AMBIGUOUS'; end if;
   select * into product from public.products where lower(trim(products.barcode))=lower(code) or lower(products.sku)=lower(code);
   if not found then
    if length(code)>32 or code !~ '^[A-Za-z0-9][A-Za-z0-9._-]{2,31}$' or lower(code) like 'k2-sku-%' then raise exception 'K2_PACKING_BARCODE_REQUIRED'; end if;
    sku:=public.generate_k2_sku_internal();
    insert into public.products(sku,barcode,name,status,published,is_human_reviewed,slug,internal_notes)
    values(sku,code,'Unreviewed item '||code,'Draft',false,false,lower(sku),
      'Unfinished packing Draft. Barcode observed during Italy packing; product details require human review.') returning * into product;
    insert into public.audit_logs(table_name,record_id,action,new_data,user_id)
    values('products',product.id::text,'INSERT',jsonb_build_object('source','milan_packing','sku',product.sku,'barcode',code,'is_human_reviewed',false),p_actor);
   end if;
   select * into i from public.consignment_items where consignment_id=c.id and consignment_items.sku=product.sku
     and box_code=trim(p->>'boxCode') and batch_code=trim(p->>'batchCode') for update;
   if found then
    if i.packing_removed_at is not null then raise exception 'K2_PACKING_ITEM_REMOVED'; end if;
    if i.best_before_date<>expiry then raise exception 'K2_PACKING_LOT_MISMATCH'; end if;
   else
    insert into public.consignment_items(consignment_id,sku,batch_code,box_code,best_before_date,expected_qty,packing_count_only)
      values(c.id,product.sku,trim(p->>'batchCode'),trim(p->>'boxCode'),expiry,0,true) returning * into i;
   end if;
  end if;
  if i.italy_packed_qty+delta not between 0 and 100000 then raise exception 'K2_PACKING_COUNT_INVALID'; end if;
  before_row:=to_jsonb(i);
  update public.consignment_items set italy_packed_qty=italy_packed_qty+delta where id=i.id returning * into i;
 elsif op in ('remove','restore') then
  if (p-array['operation','consignmentId','itemId','packingRevision','reason'])<>'{}' then raise exception 'K2_ADMIN_PAYLOAD_INVALID'; end if;
  select * into i from public.consignment_items where id=(p->>'itemId')::uuid and consignment_id=c.id for update;
  if not found or i.manila_scanned_qty<>0 then raise exception 'K2_PACKING_LOT_MISMATCH'; end if;
  before_row:=to_jsonb(i);
  if op='remove' then
   if i.packing_removed_at is not null then raise exception 'K2_PACKING_ITEM_REMOVED'; end if;
   update public.consignment_items set packing_removed_snapshot=before_row,packing_removed_at=clock_timestamp(),
      expected_qty=0,italy_packed_qty=0 where id=i.id returning * into i;
  else
   removed:=i.packing_removed_snapshot;
   if i.packing_removed_at is null or removed is null then raise exception 'K2_PACKING_LOT_MISMATCH'; end if;
   update public.consignment_items set expected_qty=(removed->>'expected_qty')::integer,
     italy_packed_qty=(removed->>'italy_packed_qty')::integer,packing_removed_at=null,packing_removed_snapshot=null where id=i.id returning * into i;
  end if;
 elsif op in ('cancel','reopen','dispatch') then
  if (p-array['operation','consignmentId','packingRevision','reason','acknowledgeVariance'])<>'{}' then raise exception 'K2_ADMIN_PAYLOAD_INVALID'; end if;
  before_row:=to_jsonb(c);
  if op='dispatch' then
   if not exists(select 1 from public.consignment_items where consignment_id=c.id and packing_removed_at is null and italy_packed_qty>0)
      then raise exception 'K2_PACKING_EMPTY'; end if;
   if exists(select 1 from public.consignment_items where consignment_id=c.id and packing_removed_at is null
     and not packing_count_only and expected_qty<>italy_packed_qty) and coalesce(p->'acknowledgeVariance','false'::jsonb)<>'true'::jsonb
      then raise exception 'K2_PACKING_VARIANCE_REQUIRED'; end if;
   update public.consignments set status='In_Transit',packed_at=clock_timestamp(),packing_revision=packing_revision+1 where id=c.id;
  else
   update public.consignments set packing_cancelled_at=case when op='cancel' then clock_timestamp() else null end,
     packing_revision=packing_revision+1 where id=c.id;
  end if;
 else raise exception 'K2_ADMIN_PAYLOAD_INVALID';
 end if;
 if i.id is not null then
  insert into public.audit_logs(table_name,record_id,action,old_data,new_data,user_id)
   values('consignment_items',i.id::text,'UPDATE',before_row,to_jsonb(i)||jsonb_build_object('packing_operation',op,'source',p->>'source','reason',p->>'reason'),p_actor);
 else
  insert into public.audit_logs(table_name,record_id,action,old_data,new_data,user_id)
   select 'consignments',c.id::text,'UPDATE',before_row,to_jsonb(x)||jsonb_build_object('packing_operation',op,'reason',p->>'reason'),p_actor from public.consignments x where id=c.id;
 end if;
 select * into c from public.consignments where id=c.id;
 return jsonb_build_object('consignmentId',c.id,'operation',op,'itemId',i.id,'sku',i.sku,
  'italyPackedQty',i.italy_packed_qty,'packingRevision',c.packing_revision,'status',c.status,'historicalReceipt',true);
end $function$

CREATE OR REPLACE FUNCTION k2_private.finalize_consignment_receipt_v1(p_consignment_id uuid, p_notes text, p_hub text, p_custodian text)
 RETURNS consignments
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_manifest public.consignments; v_item public.consignment_items; v_balance public.inventory_balances; v_missing integer; v_status text;
  v_saved public.product_batches; v_before_balance public.inventory_balances;
  v_sku text; v_sellable integer;
  v_today date; v_instant timestamptz; v_depth integer; v_minimum integer; v_days numeric;
begin
  if not public.is_staff() then raise exception 'Staff access required'; end if;
  perform k2_private.lock_category_policy_v1(false);
  select maximum_depth into v_depth from k2_private.category_policy_command_config where singleton;
  if v_depth is null or v_depth<1 then
    raise exception using errcode='55000',message='K2_CATEGORY_POLICY_NOT_CONFIGURED';
  end if;
  if not exists(select 1 from public.hubs h join public.custodians c on c.hub_id=h.id
    where h.id=p_hub and h.id='HUB-MNL-CENTRAL' and h.country='PH' and c.id=p_custodian) then
    raise exception 'K2_RECEIVING_CUSTODY_INVALID'; end if;
  select * into v_manifest from public.consignments where id = p_consignment_id for update;
  if not found then raise exception 'Consignment not found'; end if;
  if v_manifest.status = 'Completed' then raise exception 'K2_RECEIVING_ALREADY_COMPLETED'; end if;
  if v_manifest.status <> 'Arrived_Manila' then raise exception 'Consignment must be in Arrived Manila state'; end if;
  if not exists (select 1 from public.consignment_items where consignment_id = p_consignment_id) then raise exception 'Cannot finalize an empty manifest'; end if;

  -- Acquire every common SKU balance before product/lot work, in SKU order.
  for v_sku in select distinct sku from public.consignment_items where consignment_id=p_consignment_id order by sku
  loop
    insert into public.inventory_balances(sku,location_code,on_hand,reserved)
    select v_sku,'MANILA_MAIN',coalesce(sum(b.quantity),0)::integer,coalesce(sum(b.reserved_quantity),0)::integer
    from public.product_batches b where b.sku=v_sku
    on conflict(sku,location_code) do nothing;
    perform 1 from public.inventory_balances where sku=v_sku and location_code='MANILA_MAIN' for update;
  end loop;
  perform 1 from public.products where sku in (select sku from public.consignment_items where consignment_id=p_consignment_id)
    order by sku for update;
  perform 1 from public.consignment_items where consignment_id=p_consignment_id order by sku,id for update;
  perform 1 from public.product_batches where sku in (
    select sku from public.consignment_items where consignment_id=p_consignment_id
  ) order by sku,id for update;
  -- One internal server instant after every existing affected resource lock.
  v_instant:=k2_private.start_category_lot_context_v1(v_depth);
  v_today:=(v_instant at time zone 'Asia/Manila')::date;
  for v_item in select * from public.consignment_items where consignment_id = p_consignment_id order by sku,id for update
  loop
    select * into v_before_balance from public.inventory_balances where sku=v_item.sku and location_code='MANILA_MAIN';
    if v_item.manila_scanned_qty > 0 then
      select k2_private.effective_category_minimum_v1(p.category_id,v_depth) into v_minimum
      from public.products p where p.sku=v_item.sku;
      if v_minimum is null then
        raise exception using errcode='23514',message='K2_CATEGORY_POLICY_TAXONOMY_INVALID';
      end if;
      v_days:=null;
      if v_item.best_before_date is not null and pg_catalog.isfinite(v_item.best_before_date) then
        v_days:=(v_item.best_before_date-date '2000-01-01')::numeric-(v_today-date '2000-01-01')::numeric;
      end if;
      v_status := case when v_days>=v_minimum then 'available' else 'quarantine' end;
      insert into public.product_batches (
        sku, box_code, batch_code, quantity, quantity_available, reserved_quantity,
        expiry_date, best_before_date, landed_date, hub, custodian, arrival_flight,
        inventory_status, source_consignment_item_id, unit_cost, updated_at
      ) values (
        v_item.sku, v_item.box_code, v_item.batch_code,
        v_item.manila_scanned_qty, v_item.manila_scanned_qty, 0,
        v_item.best_before_date, v_item.best_before_date, v_today,
        p_hub, p_custodian, v_manifest.manifest_code, v_status, v_item.id, v_item.unit_cost, now()
      ) returning * into v_saved;
      insert into public.inventory_balances (sku, location_code, on_hand)
      values (v_item.sku, 'MANILA_MAIN', v_item.manila_scanned_qty)
      on conflict (sku, location_code) do update set on_hand = inventory_balances.on_hand + excluded.on_hand, updated_at = now();
      select * into v_balance from public.inventory_balances where sku = v_item.sku and location_code = 'MANILA_MAIN';
      perform set_config('k2.allow_stock_write', 'on', true);
      select coalesce(sum(greatest(b.quantity-b.reserved_quantity,0)),0)::integer into v_sellable
      from public.product_batches b where b.sku=v_item.sku and k2_private.lot_is_eligible_for_category_v1(b,v_depth,v_instant);
      update public.products set stock_available=v_sellable,total_stock=v_sellable where sku=v_item.sku;
      insert into public.inventory_events (sku, location_code, event_type, quantity, reference_type, reference_id, reason, actor_id, metadata)
      values (v_item.sku, 'MANILA_MAIN', 'received', v_item.manila_scanned_qty, 'consignment', v_manifest.id,
        p_notes, auth.uid(), jsonb_build_object('manifest', v_manifest.manifest_code, 'batch_code', v_item.batch_code,
        'box_code', v_item.box_code, 'inventory_status', v_saved.inventory_status,
        'batch_id',v_saved.id,'source_consignment_item_id',v_item.id,'hub',v_saved.hub,'custodian',v_saved.custodian,
        'quantity_available',v_saved.quantity_available,'batch_after',to_jsonb(v_saved),
        'balance_before',to_jsonb(v_before_balance),'balance_after',to_jsonb(v_balance)));
    end if;
    v_missing := v_item.italy_packed_qty - v_item.manila_scanned_qty;
    if v_missing > 0 then
      insert into public.inventory_events (sku, location_code, event_type, quantity, reference_type, reference_id, reason, actor_id, metadata)
      values (v_item.sku, 'MANILA_MAIN', 'reconciled', v_missing, 'consignment', v_manifest.id,
        p_notes, auth.uid(), jsonb_build_object('result', 'missing_on_arrival', 'manifest', v_manifest.manifest_code,
        'batch_code', v_item.batch_code, 'box_code', v_item.box_code,
        'source_consignment_item_id',v_item.id,'hub',p_hub,'custodian',p_custodian,
        'expected_qty',v_item.expected_qty,'italy_packed_qty',v_item.italy_packed_qty,'manila_scanned_qty',v_item.manila_scanned_qty));
    end if;
  end loop;
  update public.consignments set status = 'Completed', arrived_at = coalesce(arrived_at, now())
  where id = p_consignment_id returning * into v_manifest;
  perform k2_private.clear_category_lot_context_v1();
  return v_manifest;
end;
$function$

CREATE OR REPLACE FUNCTION k2_private.guard_consignment_packing_line_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c public.consignments;
begin
 if tg_op='DELETE' then raise exception 'K2_PACKING_HISTORY_PROTECTED'; end if;
 if tg_op='UPDATE' and new.consignment_id is distinct from old.consignment_id then raise exception 'K2_PACKING_LOT_MISMATCH'; end if;
 select * into c from public.consignments where id=new.consignment_id for update;
 if not found then raise exception 'K2_PACKING_LOT_MISMATCH'; end if;
 if tg_op='INSERT' or row(new.sku,new.batch_code,new.box_code,new.best_before_date,new.expected_qty,new.italy_packed_qty,
   new.packing_count_only,new.packing_removed_at,new.packing_removed_snapshot)
   is distinct from row(old.sku,old.batch_code,old.box_code,old.best_before_date,old.expected_qty,old.italy_packed_qty,
   old.packing_count_only,old.packing_removed_at,old.packing_removed_snapshot) then
  if c.status<>'Packing_Italy' or c.packing_cancelled_at is not null then raise exception 'K2_PACKING_CLOSED'; end if;
  update public.consignments set packing_revision=packing_revision+1 where id=c.id;
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION k2_private.verify_admin_bff_request(p_action text, p_timestamp bigint, p_nonce uuid, p_idempotency_key uuid, p_payload_text text, p_signature text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := auth.uid();
  v_secret bytea;
  v_payload_hash text;
  v_expected text;
  v_message text;
  v_bucket_start timestamptz;
  v_actor_hits integer;
  v_global_hits integer;
begin
  if v_actor is null or not public.is_staff() then
    raise exception using errcode='42501',message='K2_ADMIN_ACCESS_REQUIRED';
  end if;
  if coalesce(auth.jwt()->>'aal','')<>'aal2' then
    raise exception using errcode='42501',message='K2_ADMIN_AAL2_REQUIRED';
  end if;
  if p_action is null or p_timestamp is null or p_nonce is null
     or p_idempotency_key is null or p_payload_text is null or p_signature is null then
    raise exception using errcode='22023',message='K2_ADMIN_REQUEST_INVALID';
  end if;
  if p_action not in ('reference_create','cancel_order','delivery_express_quote','delivery_customer_rates_publish',
    'confirm_order', 'packing_scan', 'payment_status', 'delivery_details',
    'fulfill_order', 'transfer_lot', 'assign_box',
    'inbox_internal_note', 'inbox_mark_read', 'inbox_workflow',
    'pasabuy_transition', 'pasabuy_quote',
    'intake_session_create', 'intake_session_step', 'intake_draft',
    'intake_inventory', 'intake_publication', 'intake_evidence_register',
    'consignment_create', 'consignment_add_line', 'consignment_scan',
    'consignment_advance', 'consignment_finalize','consignment_packing',
    'lots_reconcile', 'lot_clearance',
    'coupon_create', 'coupon_state', 'coupon_archive',
    'admin_session_register', 'admin_session_validate',
    'admin_session_revoke_current', 'admin_session_revoke_one', 'admin_session_revoke_all',
    'admin_session_list',
    'catalog_import_chunk',
    'wholesale_inquiry_review',
    'admin_mfa_replacement_requested', 'admin_mfa_replacement_completed',
    'product_media_upload', 'product_media_assign', 'product_media_cleanup_complete',
    'product_media_orphan_cleanup', 'product_media_orphan_cleanup_complete',
    'globe_config_update', 'review_create', 'review_update', 'review_publish', 'review_withdraw',
    'supplier_create',
    'channel_internal_event_verify', 'website_listing_set',
    'staff_role_change', 'admin_delete_pin_set',
    'product_sku_merge', 'product_master_update', 'product_master_status', 'product_master_delete',
    'category_policy_set', 'category_policy_clear',
    'inbox_send_reply', 'product_knowledge_save', 'product_family_save',
    'ai_spend_controls_update'
  ) then
    raise exception using errcode='22023',message='K2_ADMIN_ACTION_INVALID';
  end if;
  if p_payload_text is null or octet_length(convert_to(p_payload_text, 'UTF8')) >
       (case when p_action='catalog_import_chunk' then 1048576 else 16384 end)
     or p_signature !~ '^[0-9a-f]{64}$' then
    raise exception using errcode='22023',message='K2_ADMIN_REQUEST_INVALID';
  end if;
  if abs(extract(epoch from clock_timestamp())::bigint - p_timestamp)>300 then
    raise exception using errcode='28000',message='K2_ADMIN_SIGNATURE_EXPIRED';
  end if;
  select request_secret into v_secret
  from k2_private.admin_bff_secrets where singleton = true;
  if v_secret is null then
    raise exception using errcode='55000', message='K2_ADMIN_BOUNDARY_NOT_CONFIGURED';
  end if;

  v_payload_hash := encode(extensions.digest(convert_to(p_payload_text, 'UTF8'), 'sha256'), 'hex');
  v_message := p_action || E'\n' || p_timestamp::text || E'\n' || p_nonce::text
    || E'\n' || v_actor::text || E'\n' || p_idempotency_key::text || E'\n' || v_payload_hash;
  v_expected := encode(extensions.hmac(convert_to(v_message, 'UTF8'), v_secret, 'sha256'), 'hex');
  if extensions.digest(convert_to(v_expected, 'UTF8'), 'sha256')
     <> extensions.digest(convert_to(p_signature, 'UTF8'), 'sha256') then
    raise exception using errcode='28000', message='K2_ADMIN_SIGNATURE_INVALID';
  end if;

  v_bucket_start := date_trunc('minute', clock_timestamp());
  delete from k2_private.admin_request_rate_buckets
  where bucket_start < v_bucket_start - interval '1 day';
  insert into k2_private.admin_request_rate_buckets(scope, subject, bucket_start, hit_count)
  values ('actor', v_actor::text, v_bucket_start, 1)
  on conflict (scope, subject, bucket_start) do update
    set hit_count = k2_private.admin_request_rate_buckets.hit_count + 1
  returning hit_count into v_actor_hits;
  if v_actor_hits > 360 then
    raise exception using errcode='54000', message='K2_ADMIN_RATE_LIMITED';
  end if;
  insert into k2_private.admin_request_rate_buckets(scope, subject, bucket_start, hit_count)
  values ('global', 'all_admin_requests', v_bucket_start, 1)
  on conflict (scope, subject, bucket_start) do update
    set hit_count = k2_private.admin_request_rate_buckets.hit_count + 1
  returning hit_count into v_global_hits;
  if v_global_hits > 6000 then
    raise exception using errcode='54000', message='K2_ADMIN_RATE_LIMITED';
  end if;

  delete from k2_private.admin_request_nonces where expires_at<=now();
  insert into k2_private.admin_request_nonces(actor_id,action,nonce,expires_at,verified_backend_pid,verified_transaction_id)
  values(v_actor,p_action,p_nonce,now()+interval '10 minutes',pg_backend_pid(),pg_current_xact_id()) on conflict do nothing;
  return found;
end;
$function$

CREATE OR REPLACE FUNCTION public.record_consignment_item_scan(p_consignment_id uuid, p_consignment_item_id uuid, p_stage text)
 RETURNS consignment_items
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_manifest public.consignments; v_item public.consignment_items; v_result integer;
begin
  if not public.is_staff() then raise exception 'Staff access required'; end if;
  select * into v_manifest from public.consignments where id = p_consignment_id for update;
  if not found then raise exception 'Consignment not found'; end if;
  select * into v_item from public.consignment_items
  where id = p_consignment_item_id and consignment_id = p_consignment_id for update;
  if not found then raise exception 'Manifest line not found'; end if;
  if p_stage = 'milan' then
    if v_manifest.status <> 'Packing_Italy' then raise exception 'Milan packing is closed'; end if;
    if v_item.italy_packed_qty >= v_item.expected_qty then raise exception 'Packed scans cannot exceed expected quantity'; end if;
    update public.consignment_items set italy_packed_qty = italy_packed_qty + 1
    where id = v_item.id returning * into v_item;
    v_result := v_item.italy_packed_qty;
  elsif p_stage = 'manila' then
    if v_manifest.status <> 'Arrived_Manila' then raise exception 'Consignment is not ready for Manila receiving'; end if;
    if v_item.manila_scanned_qty >= v_item.italy_packed_qty then raise exception 'Received scans cannot exceed Milan packed quantity'; end if;
    update public.consignment_items set manila_scanned_qty = manila_scanned_qty + 1,
      status = case when manila_scanned_qty + 1 = italy_packed_qty then 'Matched' else 'Discrepancy' end
    where id = v_item.id returning * into v_item;
    v_result := v_item.manila_scanned_qty;
  else raise exception 'Stage must be milan or manila';
  end if;
  insert into public.consignment_scan_events (
    consignment_id, consignment_item_id, sku, stage, resulting_qty, actor_id
  ) values (v_manifest.id, v_item.id, v_item.sku, p_stage, v_result, auth.uid());
  return v_item;
end;
$function$
